/* clang-format on */

enum {
    NUM_FILES = sizeof FILES / sizeof FILES[0],
    NUM_SCALES = sizeof SCALES / sizeof SCALES[0],
    NUM_CASES = NUM_FILES * 2 * NUM_SCALES,
};

static uint64_t fnv1a(const uint8_t *p, size_t n) {
    uint64_t h = UINT64_C(0xCBF29CE484222325);
    for (size_t i = 0; i < n; i++) {
        h = (h ^ p[i]) * UINT64_C(0x100000001B3);
    }
    return h;
}

static jpeg_expectation_t decode(const char *file, int grayscale, int scale_index) {
    char path[512];
    snprintf(path, sizeof path, "%s%s", FIXTURE_DIR, file);
    ph_context_t *ctx = NULL;
    ASSERT_OK(ph_create(&ctx));
    ASSERT_OK(ph_context_set_load_grayscale(ctx, grayscale));
    ASSERT_OK(ph_context_set_decode_scale(ctx, SCALES[scale_index]));
    ph_error_t err = ph_load_from_file(ctx, path);
    if (err != PH_SUCCESS) {
        fprintf(stderr, "[FAIL] %s: %s (%s)\n", path, ph_get_error_string(err),
                ph_get_last_error_message(ctx));
        exit(1);
    }
    ASSERT_INT_EQ(grayscale ? 1 : 3, ctx->image.channels);
    jpeg_expectation_t got = {
        file,
        grayscale,
        SCALES[scale_index],
        ctx->image.width,
        ctx->image.height,
        fnv1a(ctx->image.raw_rgb,
              (size_t)ctx->image.width * (size_t)ctx->image.height * (size_t)ctx->image.channels)};
    ph_free(ctx);
    return got;
}

static void test_decoded_pixels_match_table(void) {
    static jpeg_expectation_t got[NUM_CASES];
    int n = 0, mismatches = 0;
    for (int f = 0; f < NUM_FILES; f++) {
        for (int g = 0; g < 2; g++) {
            for (int s = 0; s < NUM_SCALES; s++, n++) {
                got[n] = decode(FILES[f], g, s);
                const jpeg_expectation_t *want =
                    n < (int)(sizeof EXPECTED / sizeof EXPECTED[0]) ? &EXPECTED[n] : NULL;
                if (!want || want->grayscale != g || want->scale != SCALES[s] ||
                    want->width != got[n].width || want->height != got[n].height ||
                    want->fnv != got[n].fnv) {
                    fprintf(stderr, "[FAIL] %s %s %s: got %dx%d %016llx\n", FILES[f],
                            g ? "gray" : "rgb", SCALE_NAMES[s], got[n].width, got[n].height,
                            (unsigned long long)got[n].fnv);
                    mismatches++;
                }
            }
        }
    }
    if (mismatches) {
        fprintf(stderr,
                "%d of %d decodes differ from the table. If the change in decoding is "
                "intended, the new table is:\n",
                mismatches, NUM_CASES);
        for (int i = 0; i < NUM_CASES; i++) {
            fprintf(stderr, "    {\"%s\", %d, %s, %d, %d, UINT64_C(0x%016llx)},\n", got[i].file,
                    got[i].grayscale, SCALE_NAMES[i % NUM_SCALES], got[i].width, got[i].height,
                    (unsigned long long)got[i].fnv);
        }
        exit(1);
    }
    ASSERT_INT_EQ(NUM_CASES, (int)(sizeof EXPECTED / sizeof EXPECTED[0]));
    PASS("test_decoded_pixels_match_table");
}

int main(void) {
    if (!ph_can_use_jpeg()) {
        printf("[SKIP] test_jpeg_variants: no native JPEG decoder in this build\n");
        return 0;
    }
    test_decoded_pixels_match_table();
    return 0;
}
